"""Layouts for the eight competition slides and the team page."""
import html
from pathlib import Path

def photo(name, alt='', cls=''):
    return f'<img class="{cls}" src="assets/{name}" alt="{html.escape(alt)}">'

def bars(rows, maximum=100):
    return ''.join(f'<div class="barrow"><span>{label}</span><i><u style="width:{value/maximum*100:.2f}%;background:{color}"></u></i><b>{str(value).replace(".",",")}%</b></div>' for label,value,color in rows)

def tag(text): return f'<div class="eyebrow">{text}</div>'
def stat(n, label): return f'<div class="stat"><strong>{n}</strong><span>{label}</span></div>'
def panel(title,body,kind=''): return f'<article class="pane {kind}">{tag(title)}{body}</article>'

def cash_chart(model):
    months=[-model['investment_rub']]+[x['cumulative_cash'] for x in model['scenarios'][1]['months']]
    xy=lambda i,v:(58+i*21,105-v/100000)
    pts=' '.join('%.1f,%.1f'%xy(i,v) for i,v in enumerate(months))
    axis=''.join(f'<text x="5" y="{y+5}">{label}</text><path d="M55 {y}h508" stroke="#d8e1ec"/>' for y,label in [(55,'+5'),(105,'0'),(155,'−5')])
    return f'<svg viewBox="0 0 590 200" class="cash">{axis}<polyline fill="none" stroke="#07f" stroke-width="5" points="{pts}"/><circle cx="415" cy="{xy(17,months[17])[1]}" r="6" fill="#e33496"/><text x="350" y="75">Окупаемость</text><text x="54" y="190">Старт</text><text x="300" y="190">12 мес.</text><text x="510" y="190">24 мес.</text></svg>'

def team():
    return '<div class="teamgrid">'+''.join('<article>'+ (photo(img,n) if img else '<div class="initial">'+initial+'</div>')+f'<h3>{n}</h3></article>' for n,img,initial in [('Егор Чуланов','egor.webp',''),('Екатерина Макаренко','kate.webp',''),('Максим Ширяев','','МШ'),('Анфиса Опарина','','АО')])+'</div><p class="take">Москва · VK Case Champ 2026</p>'

def item(title, body):
    return f'<div class="item"><h3>{title}</h3><p>{body}</p></div>'

def column(title, body):
    return f'<article class="col"><h4 class="cap">{title}</h4>{body}</article>'

def trio(*sections):
    return '<div class="trio">'+''.join(sections)+'</div>'

def ribbon(text):
    return '<div class="conclude">'+text+'</div>'

def make_pages(model):
    cover=photo('shapes.jpg','','sculpt')+photo('brand.jpg','VK Education и ВКонтакте','coverbrand')+'<div class="covercopy">'+tag('Кейс чемпионата ВКонтакте')+'<h2>Развитие элементов<br>социальной коммерции<br>для бизнес-сообществ<br>во ВКонтакте</h2><p>Пульт продаж в кабинете сообщества</p></div><div class="signature">Команда Digital Cat$ <small>Москва, 2026</small></div>'
    summary=trio(column('Выводы из анализа',stat('3 961','бизнес с активными товарами')+bars([('Включили чекаут',91.9,'#07f'),('Получили заказ',7.2,'#152e67')])+item('Продавец уже в VK','У 493 сообществ есть товары, аудитория и просмотры товарных публикаций. За месяц заказы получили 121 из них.')),
      column('Что предлагаем',item('До публикации','Пульт продаж проверяет наличие, цену и способ получения. Продавец исправляет недостающее прямо в карточке.')+item('После публикации','Покупатель открывает товар в записи. Заказ и выдача остаются в кабинете сообщества.')+item('После покупки','В Маркете покупатель находит знакомый магазин или сохранённый товар.')),
      column('Как оценим результат',stat('Заказы','считаем на каждый бизнес, попавший в тест, включая нулевые')+stat('+5 п.п.','цель по доле бизнесов хотя бы с одним заказом')+stat('17 месяцев','возврат 4,8 млн ₽ при 6 000 активных продавцах в базовом сценарии')))
    segment=trio(column('Кого берём в пилот',stat('9 754','бизнеса в исходной выборке')+item('3 961 → 1 117','Оставляем бизнесы с активными товарами, затем выбираем тех, у кого есть просмотры товарного контента.')+item('1 117 → 493','Оставляем сообщества с аудиторией свыше 1 000 и до 100 000 подписчиков.')),
      column('Кто уже продаёт','<h3>1–10 тыс. подписчиков</h3>'+bars([('Есть просмотры',21.2,'#07f'),('Нет просмотров',6.2,'#98aac4')],50)+'<small>84 из 396 против 66 из 1 059</small><h3>10–100 тыс. подписчиков</h3>'+bars([('Есть просмотры',38.1,'#07f'),('Нет просмотров',18.9,'#98aac4')],50)+'<small>37 из 97 против 25 из 132</small>'),
      column('Что нужно продавцу',photo('seller.jpg','Работа продавца','sellerphoto')+item('372 без заказа','Этим продавцам уже есть что показать аудитории. Проверим, помогает ли понятный способ получения довести интерес до покупки.')+item('121 с заказами','Для действующих продавцов проверим повторные покупки и время обработки заказа.')))
    channels=trio(column('Где возникает спрос',item('Ozon · поиск','Покупатель знает, что ищет. Витрина помогает сравнить ассортимент.')+item('leboncoin · объявление','Условия конкретной сделки покупатель уточняет у продавца.')+item('TikTok Shop · контент','Товар открывается из видео или эфира автора.')),
      column('Что даёт ВКонтакте',item('Продавцу','Можно показать товар подписчикам, ответить на вопрос и принять заказ в одном сообществе.')+item('Покупателю','Цена и получение видны ещё до заказа. Вернуться можно к магазину, которому покупатель уже доверяет.')+item('Платформе','Считаем дополнительные заказы внутри VK и бизнесы, впервые подключившие инструменты продаж.')),
      column('Где открыть товар',bars([('Витрина',39.1,'#07f'),('Лента и клипы',18.6,'#49a2ff'),('Главная Маркета',0.21,'#1b3463'),('Другое',40.2,'#9aaabd')],50)+item('Роль Маркета','Проверяем возврат к сохранённому товару. Низкая доля входов с главной сама по себе не доказывает, что отдельная витрина бесполезна.')))
    product='<div class="devicegrid"><div class="deviceart">'+photo('mac-shop.webp','Кабинет продавца на MacBook Pro','mac')+photo('phone-shop.webp','Карточка покупателя на iPhone','iphone')+'</div><div>'+item('1. Продавец видит пробел','В карточке есть цена и остаток. Пульт предлагает добавить самовывоз или доставку и прикрепить товар к записи.')+item('2. Покупатель видит условия','Из записи он открывает ту же карточку. Стоимость и получение известны до оформления.')+item('3. Заказ получает статус','Продавец подтверждает выдачу или отменяет заказ. Так можно отличить оформление от продажи, которая состоялась.')+'</div></div>'
    journey='<div class="cjm"><div></div><b>Первый контакт</b><b>Публикация</b><b>Покупка</b><b>Возврат</b>'+''.join('<strong>'+head+'</strong>'+''.join('<span>'+v+'</span>' for v in vals) for head,vals in [
        ('Продавец',['Открывает кабинет сообщества','Добавляет товар в запись или клип','Видит заказ, подтверждает получение','Повторяет запись по итогам продаж']),
        ('Покупатель',['Видит публикацию знакомого магазина','Открывает карточку по товарной метке','Выбирает получение и оформляет заказ','Находит магазин в сохранённых']),
        ('Где теряется заказ',['Каталог пуст или товар скрыт','Товар показан, но карточка не прикреплена','Способ получения не указан','Трудно найти тот же товар']),
        ('Что меняем',['Новичку: создать товар. Продавцу: выбрать готовый','Подсказка вставляет карточку в публикацию','Проверка условий до публикации','Маркет показывает знакомые товары']),
        ('Что измеряем',['Первое подключение инструмента','Открытие из записи','Заказы, выдачи, отмены','Повторный заказ за 30 дней'])])+'</div>'
    econ='<div class="duo">'+column('Когда вернутся вложения',cash_chart(model)+'<p>Накопленный денежный поток, млн ₽. Первые полгода число активных продавцов растёт до 6 000.</p>'+item('4,8 млн ₽ на запуск','3,15 млн на разработку, 600 тыс. на аналитику, 450 тыс. на исследование и подключение. Инфраструктура и резерв по 300 тыс. ₽.'))+column('Что должно сойтись',item('1,8 млн ₽ выручки в месяц','При 6 000 активных бизнесов каждый пятый тратит на рекламу на 1 500 ₽ больше, чем потратил бы без продукта.')+item('410 тыс. ₽ после расходов','65% маржи дают 1,17 млн ₽. Вычитаем 360 тыс. ₽ на поддержку и 400 тыс. ₽ постоянных расходов.')+item('Граница окупаемости','Операционный результат становится положительным при 2 963 активных бизнесах. При осторожном сценарии ежемесячный убыток составляет 325 тыс. ₽.'))+'</div>'
    pilot='<div class="milestones">'+''.join('<div><b>'+a+'</b><h3>'+b+'</h3><p>'+c+'</p></div>' for a,b,c in [('Недели 1–2','Исследование','Разобрать сорванные заказы с продавцами. Проверить карточки и условия получения.'),('Недели 3–6','Разработка','Связать публикацию, товар и заказ. Разделить оформления, выдачи и отмены.'),('Недели 7–8','Пробный запуск','50–100 бизнесов. Пройти путь от публикации до выдачи и сверить события.'),('С 9-й недели','Эксперимент','Случайно назначить группы. Для каждого бизнеса выдержать полные 30 дней.')])+'</div>'+trio(column('Заказы',stat('9 334','бизнеса в каждой группе для обнаружения роста на 20% при текущем разбросе')),column('Охват продавцов',stat('1 238','бизнесов на группу для проверки роста доли продающих с 24,5% до 29,5%')),column('Решение','<p>Расширяем пилот, если прирост заказов подтверждён, дополнительная маржа положительна, отмены и жалобы в согласованных пределах.</p>'))
    summary+=ribbon('<b>Решение для VK.</b> Начать с продавцов, у которых уже есть товар и просмотры. Сначала проверить, даёт ли кабинет больше заказов, затем расширять продвижение и рекомендации Маркета.')
    segment+=ribbon('<b>Почему начинать здесь?</b> На эти 493 сообщества приходится 1 869 из 3 478 заказов в выборке бизнесов. Это 5,1% бизнесов и 53,7% заказов. Разница между группами ещё не доказывает эффект контента.')
    channels+=ribbon('<b>Первое вложение:</b> кабинет продавца. Покупку охвата и субсидии откладываем до проверки конверсии готовых карточек. Сравнение пяти инициатив и затрат на с. 16.')
    product+=ribbon('<b>Что изменилось для покупателя:</b> в публикации и при оформлении он видит одну карточку с актуальным наличием. Вопрос о получении можно решить до заказа.')
    econ+=ribbon('<b>Порог рекламы:</b> при 6 000 активных продавцах и остальных базовых условиях операционные расходы покроются, если рекламу на 1 500 ₽ в месяц дополнительно купят примерно 13% продавцов.')
    return [('',cover),('Магазины подключают продажи, но редко получают заказ',summary),('Для пилота отобрали 493 сообщества с товарами и аудиторией',segment),('Покупка во ВКонтакте начинается со знакомства с товаром',channels),('Пульт продаж связывает карточку, публикацию и заказ',product),('Путь покупателя и продавца от первой записи до повторного заказа',journey),('При базовом спросе на рекламу вложения возвращаются на 17-м месяце',econ),('Сколько продавцов нужно, чтобы отличить рост заказов от случайности',pilot)]

def architecture():
    return '<div class="system">'+''.join('<div><small>'+a+'</small><h3>'+b+'</h3><p>'+c+'</p></div>' for a,b,c in [('Сообщество','Каталог','Цена, остаток, получение. Единый идентификатор товара.'),('Контент','Запись и клип','Ссылка на карточку сохраняет идентификатор публикации.'),('Оформление','Заказ','Связь с продавцом, товаром и публикацией. Повтор запроса не создаёт второй заказ.'),('Исполнение','Кабинет продавца','Подтверждение, отмена или выдача. История изменений статуса.')])+'</div>'+trio(column('Маркет','<p>Показывает сохранённые товары и знакомые сообщества. Перед показом цены и наличия читает актуальную карточку.</p>'),column('Аналитика','<p>Связывает открытие, оформление и выдачу по ID. Повторные события удаляются по идентификатору операции.</p>'),column('Эксперимент','<p>Закрепляет группу за бизнесом. Заказы считаются по всем поверхностям, чтобы заметить перенос из старых каналов.</p>'))

